const CUT_MARKER = "**End of the reviewer path.**";

/** Split a steering document at the zone cut. Returns null if the cut is missing. */
export function splitZones(text: string): { zoneA: string; zoneB: string } | null {
  const i = text.indexOf(CUT_MARKER);
  if (i < 0) return null;
  const after = text.indexOf("\n", i);
  return { zoneA: text.slice(0, after < 0 ? text.length : after), zoneB: text.slice(after < 0 ? text.length : after) };
}

/** Deterministic lint: the mechanical half of the format, enforced by code. */
export function lintSteeringDoc(path: string): string[] {
  if (!existsSync(path)) return []; // missing-output problem is reported by the runner
  const text = readFileSync(path, "utf8");
  const problems: string[] = [];
  const zones = splitZones(text);
  if (!zones) {
    return [
      `the document must contain the literal zone cut line "${CUT_MARKER}" separating Zone A (reviewer path) from Zone B`,
    ];
  }
  const nonblank = zones.zoneA.split("\n").filter((l) => l.trim().length > 0).length;
  if (nonblank > 200) {
    problems.push(
      `Zone A has ${nonblank} nonblank lines; the hard cap is 200. Demote to Zone B or the evidence file — do not compress by making lines denser.`,
    );
  }
  // Companion word budget: the line cap alone invites density gaming.
  const words = zones.zoneA.split(/\s+/).filter(Boolean).length;
  if (words > 2600) {
    problems.push(
      `Zone A has ${words} words; the budget is 2600. The cap measures reviewer reading time — demote or cut, don't densify.`,
    );
  }
  for (const section of ["## The bet", "## Where to push back", "## Decisions", "## Shape", "## Assumptions", "## Not doing", "## Done looks like"]) {
    if (!zones.zoneA.includes(section)) problems.push(`Zone A is missing required section "${section}"`);
  }
  for (const section of ["## Contracts", "## Behaviour and edge cases", "## Build order", "## Glossary delta", "## Facts on file", "## UNVERIFIED", "## Prior art"]) {
    if (!zones.zoneB.includes(section)) problems.push(`Zone B is missing required section "${section}"`);
  }
  if (!/\bdraft\b/i.test(zones.zoneA.split("\n").slice(0, 6).join("\n"))) {
    problems.push("the header must carry status `draft` (approval is the human's utterance, never the author's)");
  }
  const fencesA = zones.zoneA.match(/```[\s\S]*?```/g) ?? [];
  const bigFences = fencesA.filter((f) => f.split("\n").length > 12);
  if (fencesA.length > 2 || bigFences.length > 0) {
    problems.push(
      `Zone A contains ${fencesA.length} fenced block(s)${bigFences.length ? `, ${bigFences.length} longer than 12 lines` : ""}; ` +
        "snippets live in Zone B Contracts unless they encode a decision more precisely than prose can, and never run long.",
    );
  }
  if (!zones.zoneA.includes("⚠")) {
    problems.push("no decision is marked ⚠ (most-irreversible-first ranking requires flagging expensive reversals; if truly none is expensive, say so under Where to push back)");
  }
  if ((zones.zoneA.match(/\*Instead of:\*/g) ?? []).length < 3) {
    problems.push("decisions must carry *Instead of:* (the alternative that was real, and lost) — fewer than 3 do");
  }
  // Classification is a per-Decision property, so the check is per Decision:
  // an aggregate tally accepts one Decision carrying two markers while its
  // neighbour carries none. A block is a `### D` heading and everything until
  // the next one; only a line OPENING with the marker classifies.
  const blocks = zones.zoneA.split(/(?=^### D)/m).filter((b) => b.startsWith("### D"));
  for (const block of blocks) {
    const heading = (block.split("\n", 1)[0] ?? "").trim();
    const markers = block.split("\n").filter((l) => l.startsWith("*Enforced:*")).length;
    if (markers !== 1) {
      problems.push(
        `"${heading}" has ${markers} line(s) opening with *Enforced:*; each decision carries exactly one — ` +
          "either the choke point that decides it (named as Shape or Contracts names it) or the literal `stated, not enforced`.",
      );
    }
  }
  return problems;
}

